class Mesin {
    int cc;

    Mesin(int cc) {
        this.cc = cc;
    }

    void nyala() {
        System.out.println("Mesin " + cc + "cc menyala");
    }
}

class Mobil {
    String merek;
    Mesin mesin;

    Mobil(String merek, Mesin mesin) {
        this.merek = merek;
        this.mesin = mesin;
    }

    void jalan() {
        mesin.nyala();
        System.out.println(merek + " mulai berjalan");
    }
}

