public class Main {
    public static void main(String[] args) {
        Laptop l = new Laptop(new Baterai());
        l.nyalakan();
    }
}

class Baterai {
    void isi() {
        System.out.println("Baterai terisi");
    }
}

class Laptop {
    Baterai baterai;

    Laptop(Baterai baterai) {
        this.baterai = baterai;
    }

    void nyalakan() {
        baterai.isi();
        System.out.println("Laptop menyala");
    }
}
